\begin{proposition}[the demand is one-sided, and its threshold is not
a log power]\label{prop:onesided}
In the Corollary-1 regime, binary Goldbach for all sufficiently large
even $N$ follows from
\begin{equation}\label{eq:onesided}
  E_3(\alpha)\;>\;-\,\SS(N)\bigl(1-\AAA(N)\bigr)N\,\bigl(1+o(1)\bigr),
\end{equation}
with $\AAA(N)$ as in \eqref{eq:AN}. This is strictly weaker than
$E_3\ll_A N(\log N)^{-A}$ in two independent ways: it constrains $E_3$
from one side only, and its threshold is $\SS(N)(1-\AAA(N))N$, which
is $\asymp N$ for almost all even $N$ and never smaller than
$c\,N/(\log N\log\log N)$ for an absolute constant $c>0$.
\end{proposition}

\begin{proposition}[the demand needs no saving in $\log N$]%
\label{prop:nolog}
Put
\begin{equation}\label{eq:Bsum}
  B(N)\;:=\;\sum_{\substack{k<K\\ (k,N)=1}}
     \mu^2(k)\,(\log k)\,\bigl|\Emu(N;k)\bigr|,
\end{equation}
the restriction to squarefree $k$ being what the triangle inequality
on \eqref{eq:E3} leaves, since $\mu(k)=0$ elsewhere. This is sharper than the quantity
\cite{HL} actually reach before appealing to $EH_\mu$, namely
$\log N\sum_{k<K,(k,N)=1}|\Emu(N;k)|$, in which $\log k$ has been
raised to $\log N$; the proposition below holds for either, and a
fortiori for theirs. Then binary Goldbach for all sufficiently large
even $N$ follows from
\begin{equation}\label{eq:nolog}
  B(N)\;\le\;(1-\varepsilon)\,\SS(N)\bigl(1-\AAA(N)\bigr)N
\end{equation}
for a single fixed $\varepsilon>0$. Since $\SS(N)(1-\AAA(N))\asymp1$
for almost all even $N$, \eqref{eq:nolog} is a \emph{constant-factor}
bound on exactly the object $EH_\mu$ bounds --- absolute values kept,
and no saving in $\log N$ whatsoever --- where $EH_\mu(N^{\theta'})$
asks for $\ll_A N(\log N)^{-A}$ for every $A$.
\end{proposition}

\begin{lemma}\label{lem:complete}
For squarefree $u\ge1$,
$\displaystyle\sum_{k\mid u,\ (k,N)=1}\mu(k)=\mathbf 1_{\rad(u)\mid N}$.
\end{lemma}

\begin{lemma}[degeneracy]\label{lem:degen}
The contribution to \eqref{eq:R1} of the terms with $(k,N)>1$ is
$O(N^{o(1)})$. The same bound holds for the terms in which the modulus
constructed in Step~4 is not coprime to $N$.
\end{lemma}

\begin{note}[the false-positive trap]\label{note:trap}
Restricting the \emph{main terms} to classes with $(q,N)=1$ is not
cosmetic. Assigning a main term $\Tcut_m/\varphi(q)$ to a degenerate class
shifts the density of the whole computation by the factor
$N/\varphi(N)$. Carried into the $\log k$ branch of
Section~\ref{sec:C}, that error produces an apparent \emph{refutation}
of $EH_\mu$. It is recorded here because it is the most plausible
false positive in this circle of ideas.
\end{note}

\begin{lemma}[$\tau$-weighted Bombieri--Vinogradov]\label{lem:BV}
For all $A,B>0$ there is $C=C(A,B)$ such that for
$Q\le N^{1/2}(\log N)^{-C}$,
\[
  \sum_{q\le Q}\tau_3(q)^{B}\ \max_{y\le N}\ \max_{(a,q)=1}
  \Bigl|\psi(y;q,a)-\frac{y}{\varphi(q)}\Bigr|
  \;\ll_{A,B}\;\frac{N}{(\log N)^{A}}.
\]
\end{lemma}

\begin{lemma}\label{lem:density}
Let $m$ be squarefree with $(m,N)=1$ and put
\[
  c(m):=\sum_{d\ge1}\ \sum_{e\mid m}
     \frac{\mu(d)\mu(e)\mathbf 1_{(d,N)=1}}{\varphi(m\lcm(d^2,e))}.
\]
Then $c(m)=\AAA(N)\lambda(m)/m$ with $\AAA(N)$ as in \eqref{eq:AN} and
$\lambda(m)=\prod_{p\mid m}\bigl(1-\tfrac{1}{p(p-1)}\bigr)^{-1}$.
Moreover $c_{D_0,E_0}(m)=c(m)+O(1/(mD_0))$.
\end{lemma}

\begin{lemma}\label{lem:mu}
Let $f(m):=\mu(m)\lambda(m)\mathbf 1_{(m,N)=1}$ and
$G(x):=\sum_{m\le x}f(m)/m$. Then
\[
  G(x)\;\ll\;\frac{N}{\varphi(N)}\,e^{-c\sqrt{\log x}}
   +x^{-1/4}e^{C\sqrt{\log N}}
   \qquad(x\ge2).
\]
\end{lemma}

\begin{proposition}\label{prop:MT}
$\displaystyle\sup_{1\le t<N}|\mathrm{MT}(t)|\ll Ne^{-c\sqrt{\log N}}$.
\end{proposition}

\begin{lemma}\label{lem:completelog}
For squarefree $u$, write $u=u_Nu'$ where $u_N$ is the largest divisor
of $u$ composed of primes dividing $N$. Then
$\sum_{k\mid u,\ (k,N)=1}\mu(k)\log k=-\Lambda(u')$.
\end{lemma}

\begin{proposition}[the bound survives the corrected cut]%
\label{prop:movingcut}
Fix $\theta'\in(1/2,1)$, put $\alpha=N^{1-\theta'}$ and
$K=(N-1)/\alpha$. Then for every $A>0$,
$T_1^\ast\ll_{A,\theta'}N(\log N)^{-A}$, unconditionally.
\end{proposition}

\begin{lemma}\label{lem:Gb}
For squarefree $u$, $\sum_{k\mid u}\mu(k)w_k=\mu(u)\,b_u$.
\end{lemma}

\begin{proposition}[the discrepancy is a dilate]\label{prop:dilate}
Unconditionally,
\begin{equation}\label{eq:dilate}
  A(N;k)\;=\;\mu(k)\,H(N;k),
  \qquad
  H(N;k)\;=\;\sum_{\substack{m<N/k\\ (m,k)=1}}\Lambda(N-mk)\,\mu(m).
\end{equation}
\end{proposition}

\begin{proposition}[the weights are nonnegative]\label{prop:posweights}
Substituting \eqref{eq:dilate} into $T_{\log}$ and using $\mu(k)^2=1$
on squarefree $k$,
\begin{equation}\label{eq:posweights}
  T_{\log}\;=\;\sum_{\substack{k<K\\(k,N)=1}}
    \mu^2(k)\,(\log k)\,H(N;k)\;-\;C(N)\,B_{\log}(K),
  \qquad
  B_{\log}(K)=\!\!\sum_{\substack{k<K\\(k,N)=1}}\!\!
     \frac{\mu(k)\log k}{\varphi(k)} .
\end{equation}
\end{proposition}

\begin{proposition}[the untruncated sum is the count]%
\label{prop:untrunc}
Summing over \emph{all} $k$, with no truncation and no coprimality
restriction,
\begin{equation}\label{eq:untrunc}
  \sum_{k\ge1}(\log k)\,\mu(k)\,A(N;k)
   \;=\;-\sum_{n<N}\Lambda(n)\,\mu(N-n)\Lambda(N-n)
   \;=\;\sum_{p<N}\Lambda(N-p)\log p .
\end{equation}
So the untruncated object \emph{is} $\tilde r(N)$, up to its
prime-power part.
\end{proposition}

\begin{proposition}[the count as signed layers]\label{prop:layers}
Cutting the same double sum along the inner variable of
\eqref{eq:dilate},
\begin{equation}\label{eq:layers}
  \sum_{k}\mu^2(k)(\log k)H(N;k)\;=\;\sum_{m}\mu(m)\,L(N;m),
  \qquad
  L(N;m):=\!\!\sum_{\substack{k<N/m,\ (k,m)=1\\ \mu(k)\neq0}}\!\!
            (\log k)\,\Lambda(N-mk),
\end{equation}
and every $L(N;m)$ is nonnegative. With
Proposition~\ref{prop:untrunc}, the Goldbach count is therefore an
alternating sum, signed by $\mu$, of nonnegative layers.
\end{proposition}

\begin{proposition}[the wall cancels out of the count]%
\label{prop:direct}
Substituting \eqref{eq:posweights} into the identity of \cite[Thm.~3]{P1},
the two occurrences of $C(N)$ carry opposite signs and cancel:
\begin{equation}\label{eq:direct}
  \tilde r(N)\;=\;\SS(N)N
   \;+\!\!\sum_{\substack{k<K\\(k,N)=1}}\!\!\mu^2(k)(\log k)H(N;k)
   \;-\;C(N)\bigl(B_{\log}(K)+\SS(N)\bigr)
   \;+\;O_A\!\left(\frac{N}{(\log N)^{A}}\right).
\end{equation}
Since $B_{\log}(K)\to-\SS(N)$, the quantity $C(N)$ enters the Goldbach
count only through the vanishing factor $B_{\log}(K)+\SS(N)$.
Consequently
\begin{equation}\label{eq:directcond}
  \sum_{\substack{k<K\\(k,N)=1}}\mu^2(k)(\log k)\bigl|H(N;k)\bigr|
   \;\le\;(1-\varepsilon)\,\SS(N)\,N
\end{equation}
suffices for $\tilde r(N)>0$, for all large even $N$.
\end{proposition}

\begin{proposition}[zero margin]\label{prop:E}
Both standard ways of estimating this integral lie at or above the
trivial bound $|C(N)|\le\psi(N)\sim N$:
\begin{enumerate}
\item[(i)] $\|S_\Lambda\|_2\|S_\mu\|_2
   =\bigl(\sum_{n\le N}\Lambda(n)^2\bigr)^{1/2}
     \bigl(\sum_{m\le N}\mu^2(m)\bigr)^{1/2}
   \sim(6/\pi^2)^{1/2}\,N(\log N)^{1/2}$, exceeding the trivial bound
   by a factor $\asymp(\log N)^{1/2}$, which \emph{grows};
\item[(ii)] any bound of the shape
  $\sup_\alpha|S_\mu(\alpha)|\cdot\|S_\Lambda\|_1$ is at least
  $\|S_\mu\|_2\|S_\Lambda\|_1\gg N^{1/2}\cdot N^{1/2}=N$.
\end{enumerate}
\end{proposition}

\begin{lemma}[exact cell moments]\label{lem:cellmom}
Let a band of even $N$ be partitioned into cells, let $c$ be a cell of
size $n_c$ inside a band of size $n$, let $m_c$ and $\overline m$ be
the means of $Z$ over $c$ and over the band, and set
\[
  u_c(v)\;=\;\sum_{N\in c}\frac{\Lambda(N-v)}{\sqrt{V(N)}},
  \qquad
  Q_{cd}\;=\;\sum_v\mu^2(v)\,u_c(v)\,u_d(v).
\]
Then, when the $\mu(v)$ on the surviving support are replaced by
independent signs,
\begin{equation}\label{eq:cellmom}
  \mathrm{Var}\bigl(m_c-\overline m\bigr)
  \;=\;\frac{Q_{cc}}{n_c^{2}}
  \;-\;\frac{2\,Q_{ca}}{n_c\,n}
  \;+\;\frac{Q_{aa}}{n^{2}},
\end{equation}
where $a$ denotes the whole band. Every term is computable exactly by
one convolution; no simulation is involved.
\end{lemma}
